nb = json.loads(NOTEBOOK.read_text(encoding="utf-8"))
new_cells = json.loads(zlib.decompress(base64.b85decode(PAYLOAD.encode("ascii"))).decode("utf-8"))

markers = (
    "## Figuras reais para a apresentação",
    "CÉLULA 5A", "CÉLULA 5B", "CÉLULA 5C", "CÉLULA 5D", "CÉLULA 5E",
)

def source_text(cell):
    src = cell.get("source", [])
    return "".join(src) if isinstance(src, list) else str(src)

# Idempotência: remove uma eventual versão anterior desta seção.
nb["cells"] = [
    cell for cell in nb["cells"]
    if not any(marker in source_text(cell) for marker in markers)
]

insert_at = None
for i, cell in enumerate(nb["cells"]):
    src = source_text(cell)
    if "CÉLULA 5 — FEATURE ENGINEERING" in src or "CÉLULA 5 - FEATURE ENGINEERING" in src:
        insert_at = i + 1
        break

if insert_at is None:
    raise RuntimeError("Não foi possível localizar a Célula 5 — Feature Engineering.")

nb["cells"][insert_at:insert_at] = new_cells
NOTEBOOK.write_text(json.dumps(nb, ensure_ascii=False, separators=(",", ":")), encoding="utf-8")
print(f"Notebook atualizado: {NOTEBOOK} | células inseridas: {len(new_cells)}")
